TypeScript example (abridged):
// start session
const s = await client.startSession({ model: 'redwood-llm-optim', features: ['streaming_structured_v1'] });
s.onEvent(e => { if (e.type === 'token') render(e.text); if (e.type === 'structured') handleStructured(e.payload); });
await s.sendInput('Summarize the following...');
// reconnect
const resumed = await client.resumeSession(s.id, { lastSeen: s.lastEventId });

Python example (abridged):
# start session
s = client.start_session(model='redwood-llm-optim', features=['streaming_structured_v1'])
for evt in s.events():
    if evt.type == 'token': print(evt.text, end='')
    elif evt.type == 'tool_call': handle_tool_call(evt.payload)
# on network drop:
resumed = client.resume_session(s.id, last_seen=s.last_event_id)

Go example (abridged):
// open websocket and read envelopes
conn, _ := client.StartSession(ctx, StartOpts{Model: 'redwood-llm-optim'})
for ev := range conn.Events() {
    switch ev.Type {
    case 'token': fmt.Print(ev.Text)
    case 'structured': var doc map[string]interface{}; json.Unmarshal(ev.Payload, &doc); process(doc)
    case 'checkpoint': cache.Put(ev.CheckpointId, ev.CheckpointData)
    }
}
// reconnect with last event id
conn = client.ResumeSession(ctx, ResumeOpts{SessionID: conn.ID, LastSeen: conn.LastEventId})
